(()=>{const URL=window.APP_CONFIG?.supabaseUrl||"https://gzdusguveeeflmlvvmwe.supabase.co";const KEY=window.APP_CONFIG?.supabasePublishableKey||"sb_publishable_nSqPHZf1-1CAJMFNmrpNqA_lafobeV-";const sb=window.supabase?.createClient?.(URL,KEY);const app=document.getElementById("newsApp");const esc=s=>String(s??"").replace(/[&<>"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[m]));const fmt=d=>new Date(d).toLocaleDateString("id-ID",{day:"2-digit",month:"long",year:"numeric"}).toUpperCase();const slug=new URLSearchParams(location.search).get("slug");async function getOne(){if(!slug)return null;const r=await sb.from("news_syndication_feed").select("*").eq("slug",slug).lte("published_at",new Date().toISOString()).maybeSingle();if(r.error)throw r.error;return r.data}async function getAll(){const r=await sb.from("news_syndication_feed").select("slug,title,excerpt,category,published_at,reading_minutes,image_key").lte("published_at",new Date().toISOString()).order("published_at",{ascending:false}).limit(20);if(r.error)throw r.error;return r.data||[]}function imageClass(k){return k==="umkm"?"photo-umkm":k==="community"?"photo-community":k==="service"?"photo-service":"photo-village"}function detail(x,all){app.innerHTML='<div class="news-page-head"><div class="news-meta"><span>'+esc(x.category)+'</span><span>·</span><span>'+fmt(x.published_at)+'</span><span>·</span><span>'+esc(x.reading_minutes)+' MIN BACA</span></div><h1>'+esc(x.title)+'</h1><p class="lead muted">'+esc(x.excerpt||"")+'</p></div><article class="news-detail"><div class="detail-image '+imageClass(x.image_key)+'"></div><div class="news-body">'+esc(x.content)+'</div><div class="source-note"><strong>Sumber editorial: Kabar Desa · Smart Village</strong>Artikel ini merupakan bagian dari lapisan informasi publik Smart Village. Jika kelak disindikasikan ke Suara Ibukota, sumber, atribusi, dan canonical article tetap merujuk pada artikel ini.</div></article><div class="section-head"><div><span class="eyebrow dark">KABAR DESA</span><h2>Berita lainnya.</h2></div></div><div class="news-list">'+all.filter(a=>a.slug!==x.slug).map(a=>'<a class="news-list-item" href="./berita.html?slug='+encodeURIComponent(a.slug)+'"><div class="news-list-image '+imageClass(a.image_key)+'"></div><div><div class="news-meta"><span>'+esc(a.category)+'</span><span>·</span><span>'+fmt(a.published_at)+'</span></div><h3>'+esc(a.title)+'</h3><p class="mb-0 muted">'+esc(a.excerpt||"")+'</p></div></a>').join("")+'</div>'}function list(all){app.innerHTML='<div class="news-page-head"><span class="eyebrow dark">KABAR DESA</span><h1>Yang sedang terjadi <em>di sekitar kita.</em></h1><p class="lead muted">Berita, cerita, dan perkembangan dari ekosistem Smart Village.</p></div><div class="news-list">'+all.map(a=>'<a class="news-list-item" href="./berita.html?slug='+encodeURIComponent(a.slug)+'"><div class="news-list-image '+imageClass(a.image_key)+'"></div><div><div class="news-meta"><span>'+esc(a.category)+'</span><span>·</span><span>'+fmt(a.published_at)+'</span></div><h3>'+esc(a.title)+'</h3><p class="mb-0 muted">'+esc(a.excerpt||"")+'</p></div></a>').join("")+'</div><div class="source-note"><strong>MEDIA LAYER</strong>Smart Village menjadi sumber berita. Suara Ibukota nantinya dapat mengonsumsi artikel yang ditandai <code>syndication_enabled</code> melalui feed/API kanonik tanpa menggandakan sumber editorial.</div>'}async function load(){try{const all=await getAll();if(slug){const one=await getOne();if(!one){list(all);return}detail(one,all)}else list(all)}catch(e){app.innerHTML='<div class="news-error"><strong>Kabar Desa belum dapat dimuat.</strong><p class="mb-0 mt-2">'+esc(e.message||"Kesalahan koneksi")+'</p></div>'}}if(sb)load();else app.innerHTML='<div class="news-error">Koneksi data publik belum tersedia.</div>'})();